/* ============================================
   APP LAYOUT — full-page template
   Sidebar rail on the left, centered content area
   ============================================ */

.ds-app-layout {
  display: flex;
  min-height: 100vh;
  background-color: var(--color-bg-page-primary);
}

/* ============================================
   MAIN CONTENT AREA
   ============================================ */
.ds-app-layout__main {
  flex: 1;
  display: flex;
  justify-content: center;
  /* The rail's width plus, while it shows, the side panel's. */
  margin-inline-start: calc(var(--ds-app-layout-rail, 64px) + var(--ds-app-layout-panel, 0px));
  padding: var(--padding-1000) var(--padding-500);
  transition: margin-inline-start var(--motion-duration-slow) var(--motion-ease-emphasized);
  min-width: 0;
}

.ds-app-layout--expanded {
  --ds-app-layout-rail: 280px;
}

/* Panel mode's collapsed rail is the wider, labelled one. */
.ds-app-layout:not(.ds-app-layout--expanded):has(.ds-app-sidebar--panel-mode) {
  --ds-app-layout-rail: 80px;
}

.ds-app-layout:has(.ds-app-sidebar__panel--visible) {
  --ds-app-layout-panel: 240px;
}

/* ============================================
   CENTERED CONTENT WRAPPER
   ============================================ */
.ds-app-layout__content {
  width: 100%;
  max-width: 1120px;
  display: flex;
  flex-direction: column;
  gap: var(--gap-1000);
}

/* ============================================
   FLOATING LAYOUT — the rail floats as a glass
   card, so the main column clears its inset on
   both sides of it
   ============================================ */
.ds-app-layout--floating .ds-app-layout__main {
  margin-inline-start: calc(
    var(--ds-app-layout-rail, 64px) + var(--ds-app-layout-panel, 0px) +
      var(--ds-sidebar-float-inset, 20px) * 2
  );
}

/* ============================================
   INSET LAYOUT — the rail flush on the shell
   colour, the content full width in a surface
   inset from the other three edges. The page
   holds the viewport and the surface scrolls.
   The rail's own item inset is the gap on its
   side, so the selected item sits evenly
   between the two edges.
   ============================================ */
.ds-app-layout--inset {
  height: 100dvh;
  min-height: 0;
  background-color: var(--color-bg-app-shell);
}

.ds-app-layout--inset .ds-app-layout__main {
  padding: var(--ds-shell-inset);
  padding-inline-start: 0;
  min-height: 0;
}

.ds-app-layout__surface {
  flex: 1;
  min-width: 0;
  display: flex;
  overflow: hidden;
  background-color: var(--color-bg-app-surface);
  border-radius: var(--radius-600);
}

.ds-app-layout__scroller {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: var(--padding-1000) var(--padding-1000);
  /* The scrollbar stays invisible until the surface scrolls (data-scrolling
     is set by the scroll handler and cleared once it settles). */
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

.ds-app-layout__scroller[data-scrolling] {
  scrollbar-color: var(--color-bg-container-border) transparent;
}

/* Full width in the surface, and a size container: content inside can
   restack by the room the surface gives it (an open chat panel or an
   expanded rail narrows it without the viewport changing) with
   @container ds-app-layout-content queries. */
.ds-app-layout--inset .ds-app-layout__content {
  max-width: none;
  container: ds-app-layout-content / inline-size;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 768px) {
  .ds-app-layout__main {
    margin-inline-start: 0;
    padding: var(--padding-500) var(--padding-400);
  }

  .ds-app-layout--expanded .ds-app-layout__main,
  .ds-app-layout--floating .ds-app-layout__main {
    margin-inline-start: 0;
  }

  /* Phones: the rail is a drawer, so the inset surface runs edge to edge
     and the page scrolls normally. */
  .ds-app-layout--inset {
    height: auto;
    min-height: 100vh;
  }

  .ds-app-layout--inset .ds-app-layout__main {
    padding: 0;
  }

  .ds-app-layout__surface {
    overflow: visible;
    border-radius: 0;
  }

  .ds-app-layout__scroller {
    overflow-y: visible;
    padding: var(--padding-500) var(--padding-400);
  }
}

'use client';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AppSidebar } from '../AppSidebar/AppSidebar';
import type { AppSidebarSection, AppSidebarProfile, AppSidebarLayout } from '../AppSidebar/AppSidebar';
import { MOTION_SCROLL_SETTLE_MS } from '../../tokens/motion';
import type { LinkComponent } from '../../behaviors/LinkProvider';
import './AppLayout.css';

/** Props owned by AppLayout itself — everything else falls through to the outer wrapper `<div>`. */
type AppLayoutOwnProps = {
  /** Sidebar navigation sections */
  sections: AppSidebarSection[];
  /** Sidebar profile */
  profile?: AppSidebarProfile;
  /** Active nav item key */
  activeKey?: string;
  /** Active sub-item key */
  activeSubKey?: string;
  /** Active third-level item key, listed in the sidebar's side panel */
  activeTertiaryKey?: string;
  /** Where sub-items show: the sidebar's accordion, or straight into its side panel (see AppSidebar) */
  subNav?: 'accordion' | 'panel';
  /** Whether sidebar starts expanded */
  defaultExpanded?: boolean;
  /** Logo text next to icon */
  logoText?: string;
  /** Custom logo element */
  logo?: React.ReactNode;
  /** Page content — centred in the main area */
  children: React.ReactNode;
  /**
   * How the rail and the content meet the page. `flush` (the default) runs
   * the rail edge to edge with the content centred beside it. `floating`
   * floats the rail as a glass card, the content still centred. `inset` runs
   * the rail flush on the app shell colour and sets the content full width
   * in a surface inset from the other edges, which scrolls inside itself.
   */
  layout?: AppSidebarLayout;
  /**
   * Colour scheme: 'dark' pins the layout to the dark theme (the historical
   * behaviour and the default); 'inherit' drops the pin so the layout
   * follows the surrounding data-theme like any other component.
   */
  theme?: 'dark' | 'inherit';
  /**
   * The component its links render with, such as Next.js's `Link`, so they
   * navigate through the app's router; passed on to the AppSidebar rail. Wins over a
   * LinkProvider's; a plain `<a>` when neither is set.
   */
  linkComponent?: LinkComponent;
  /** Additional CSS classes on outer wrapper */
  className?: string;
};

export interface AppLayoutProps
  extends AppLayoutOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof AppLayoutOwnProps> {}

/**
 * AppLayout — full-page template with a collapsible sidebar
 * and a content area, centred or set in an inset surface (see `layout`).
 *
 * The forwarded ref and any unrecognised props target the outer wrapper
 * `<div>`. With `theme="inherit"` a `data-theme` passed by the consumer
 * reaches the wrapper; with the default `dark` pin the component's own wins.
 */
export const AppLayout = React.forwardRef<HTMLDivElement, AppLayoutProps>(
  (
    {
      sections,
      profile,
      activeKey,
      activeSubKey,
      activeTertiaryKey,
      subNav,
      defaultExpanded = true,
      logoText,
      logo,
      children,
      layout = 'flush',
      theme = 'dark',
      linkComponent,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-app-layout';
    const [expanded, setExpanded] = useState(defaultExpanded);

    const handleExpandedChange = useCallback((next: boolean) => {
      setExpanded(next);
    }, []);

    // The inset surface's scrollbar shows only while it scrolls: the flag is
    // written straight to the DOM, so a scroll never re-renders the page.
    const scrollTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
    useEffect(() => () => clearTimeout(scrollTimer.current), []);
    const handleSurfaceScroll = useCallback((event: React.UIEvent<HTMLDivElement>) => {
      const scroller = event.currentTarget;
      scroller.dataset.scrolling = '';
      clearTimeout(scrollTimer.current);
      scrollTimer.current = setTimeout(() => {
        delete scroller.dataset.scrolling;
      }, MOTION_SCROLL_SETTLE_MS);
    }, []);

    const classes = [
      baseClass,
      expanded ? `${baseClass}--expanded` : '',
      layout !== 'flush' ? `${baseClass}--${layout}` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        // Spread conditionally so `inherit` leaves a consumer's own
        // data-theme in place rather than overwriting it with undefined.
        {...(theme === 'dark' ? { 'data-theme': 'dark' } : {})}
      >
        <AppSidebar
          sections={sections}
          profile={profile}
          activeKey={activeKey}
          activeSubKey={activeSubKey}
          activeTertiaryKey={activeTertiaryKey}
          subNav={subNav}
          expanded={expanded}
          onExpandedChange={handleExpandedChange}
          logoText={logoText}
          logo={logo}
          layout={layout}
          linkComponent={linkComponent}
        />
        <main className={`${baseClass}__main`}>
          {layout === 'inset' ? (
            // The surface clips to its rounded corners and the scroller
            // inside it scrolls, so the scrollbar never squares a corner.
            <div className={`${baseClass}__surface`}>
              <div className={`${baseClass}__scroller`} onScroll={handleSurfaceScroll}>
                <div className={`${baseClass}__content`}>{children}</div>
              </div>
            </div>
          ) : (
            <div className={`${baseClass}__content`}>{children}</div>
          )}
        </main>
      </div>
    );
  },
);

AppLayout.displayName = 'AppLayout';
